use super::store::WorkpoolStore;
use super::types::{PoolId,WorkpoolError,WorkpoolItemStatus,WorkpoolStatus};
pub fn reconcile_workpool(stores:&WorkpoolStore,pool_id:&PoolId)->Result<(),WorkpoolError>{let pool=stores.load(pool_id)?;if pool.status==WorkpoolStatus::Cancelled{return Ok(())}stores.mutate(pool_id,|latest|{let mut next=latest.clone();for item in &mut next.items{if item.status==WorkpoolItemStatus::Assigned&&item.binding.is_none(){item.status=WorkpoolItemStatus::Error;item.error=Some(super::types::WorkpoolYieldError{code:"delivery_uncertain".into(),message:"Delivery is uncertain.".into()});}}next.revision=latest.revision+1;next})?;Ok(())}
pub fn uncertain_item(mut item:super::types::WorkpoolItem)->super::types::WorkpoolItem{item.status=WorkpoolItemStatus::Error;item.error=Some(super::types::WorkpoolYieldError{code:"delivery_uncertain".into(),message:"Delivery is uncertain. Submit a NEW explicit key.".into()});item}
#[cfg(test)]mod tests{use super::*;use crate::workpool::types::WorkpoolItem;#[test]fn uncertain_item_changes_status(){let mut i=WorkpoolItem{key:"k".into(),input:serde_json::Value::Null,item_id:"i".into(),status:WorkpoolItemStatus::Assigned,binding:None,delivery:None,data:None,error:None,yield_sha256:None};i=uncertain_item(i);assert_eq!(i.status,WorkpoolItemStatus::Error);assert_eq!(i.error.unwrap().code,"delivery_uncertain");}}
